-- 一个 room 管理自己的 3d模型资源, 它的 children gameobjs 需要被及时 inactive, 以此来降低渲染负担


---@class Room
local Room = Class('Room')
-- 外部访问时使用:
-- local Room = import('Game.DreamSpace.Performance.RoomActivator.Room')

-- ========================================================

--- lua:

local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')

---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')

local PiecesCollection = import('Game.DreamSpace.PiecesCollection.PiecesCollection')

local RoomActivatorManager = import('Game.DreamSpace.Performance.RoomActivator.RoomActivatorManager')

local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')
---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3
local Vector4 = CS.UnityEngine.Vector4
local Quaternion = CS.UnityEngine.Quaternion
local Color = CS.UnityEngine.Color
local Time = CS.UnityEngine.Time
local Collider = CS.UnityEngine.Collider


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local LuaParameters = CS.Engine.Modules.LuaParameters
local LuaBehaviour = CS.Engine.Modules.LuaBehaviour

-- ========================================================


-- ========================================================


function Room:__init()
    
    self.isActive = true 

    self.childRoomInstanceIdsStack = {} -- 数组, {childRoomInstanceId }, 倒着删元素
    self.childRoomDic = {} -- k: instanceId, v:{ childRoomTF, isActive }

    self.isWorking = false -- 本帧是否正在 开启/关闭 room,
end



function Room:__delete()
    self.childRoomInstanceIdsStack = nil 
    self.childRoomDic = nil
end



function Room:Start()

    self.transform = self.controller.gameObject.transform

    self.params = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( self.params )

    self.isInitActive = LuaParametersReader.Read( self.params, "isInitActive", LuaParametersReader.Type.Bool ) -- room 在初始阶段是否显示
    assert( type(self.isInitActive) == "boolean" )

    DreamSpaceLuaUtils.StopCoroutine( self.co_0 )
    self.co_0 = cs_coroutine.start(self.DelayInit, self)
end


function Room:DelayInit()

    -- 需先等待每个 room 内的 EmotionalPiece 完成注册:
    cs_coroutine.yield_return( PiecesCollection.WaitInstance( true ) ) -- 等待实例化
    local piecesCollection = PiecesCollection.GetInstance()   -- 拿到唯一实例
    for i=0,DreamSpaceStates.DelayInitWaitFrames do 
        if piecesCollection.isInit == true then 
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
    end
    assert( piecesCollection.isInit == true, "始终没等到 PiecesCollection DelayInit 完成" )

    -------
    cs_coroutine.yield_return( RoomActivatorManager.WaitInstance() ) -- 等待实例化
    self.roomActivatorManager = RoomActivatorManager.GetInstance()   -- 拿到唯一实例

    if self.roomActivatorManager:GetIsIgnoreRoomHide() == true then 
        self:SetRoom( true )                -- 全体 room 默认全开
    else 
        self:SetRoom( self.isInitActive )   -- 正常流程, 按照参数指定选择 开启/隐藏
    end
end



function Room:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co_0 )
    self.co_0 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



-- ========================================================


function Room:SelfUpdate()

    self.isWorking = false 

    for i = #self.childRoomInstanceIdsStack, 1, -1 do
        self.isWorking = true

        local childInstanceId = self.childRoomInstanceIdsStack[i]
        assert( isNotNull( childInstanceId ) )
        table.remove(self.childRoomInstanceIdsStack, i)

        --- 
        local childRoom = self.childRoomDic[childInstanceId]
        assert( isNotNull( childRoom ) )
        self.childRoomDic[childInstanceId] = nil

        if childRoom.transform.gameObject.activeSelf ~= childRoom.isActive then  
            KTool.SetActive( childRoom.transform.gameObject, childRoom.isActive )
            --print( "命中 ------ " .. childRoom.transform.name )
            break
        end 
        --print( "忽略 " .. childRoom.transform.name )
    end
end



function Room:SetRoom( isActive_ )
    --print( "SetRoom: " .. self.transform.name .. " - " .. tostring(isActive_) .. ", " .. self.transform:GetInstanceID() )

    -- 每次都重新遍历 children, 防止 runtime 中 room 内被写入删除东西
    for i=0, self.transform.childCount-1, 1 do 
        local currentChildTF = self.transform:GetChild(i) -- Transform
        local childInstanceId = currentChildTF:GetInstanceID()
        
        if isNull( self.childRoomDic[childInstanceId] ) then 
            --print( "入栈 - " .. currentChildTF.name )
            table.insert( self.childRoomInstanceIdsStack, childInstanceId )
            self.childRoomDic[childInstanceId] = { transform = currentChildTF, isActive = isActive_ }

        else 
            self.childRoomDic[childInstanceId].isActive = isActive_

        end 
    end
end





return Room
